# BENCH-018: Multi-Currency Ledger & FX Reconciliation Engine

Repair only models.py, rates.py, ledger.py, and reconciler.py.
Python stdlib only; no network, sleeps, or paid services.

## API and invariants

- models.as_decimal(value) converts Decimal, integer, string, or float via
  Decimal(str(value)); reject booleans, non-finite or non-decimal values
  with ValueError. Never route through float.
- models.check_currency(code) accepts only /^[A-Z]{3}$/ codes.
- models.quantize(amount) rounds to cents with ROUND_HALF_EVEN (banker's
  rounding): 0.125 -> 0.12, 0.135 -> 0.14, 2.675 -> 2.68.
- models.Money(amount, currency) is frozen; amount normalized via
  as_decimal. add/subtract require equal currencies (else ValueError) and
  quantize the result; negate keeps the currency.
- models.Leg(account, money) is frozen; account nonempty str, money a Money.
- rates.RateTable().set_rate(base, quote, effective_at, rate): distinct
  valid currencies, timezone-aware effective_at, positive finite rate —
  violations raise ValueError.
- rates.rate(base, quote, at): same currency -> Decimal(1); otherwise the
  latest stored rate with effective_at <= at (boundary inclusive); KeyError
  when none qualifies.
- rates.convert(money, target, at): identity returns quantized Money in
  target; otherwise Money(quantize(amount * rate), target).
- ledger.Ledger().post(entry_id, legs): nonempty unique entry_id, at least
  two Leg instances, and per-currency leg sums exactly zero; violations
  raise ValueError without storing. Returns the stored legs tuple.
  entries() yields (entry_id, legs) in posting order; accounts() lists
  distinct accounts in first-use order.
- ledger.balance(account, currency=None): currency -> Money net position
  (zero Money when absent); None -> {currency: Money} sorted by code.
- reconciler.Reconciler(ledger, rates).trial_balance(account, target, at):
  every leg converted at `at` and summed into one quantized Money.
- reconciler.reconcile(expected, at): expected maps (account, currency) ->
  amount, compared against quantized actual balances. Union of keys on
  both sides (missing side = 0). Returns Discrepancy(account, currency,
  expected, actual, difference=actual-expected) sorted by
  (account, currency).

Visible tests are smoke coverage, not the complete specification.
"""Money and journal-leg value types."""
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import re

CURRENCY_RE = re.compile(r"^[A-Z]{3}$")
CENTS = Decimal("0.01")


def as_decimal(value):
    """Decimal conversion."""
    try:
        if isinstance(value, bool):
            raise ValueError("boolean amount")
        result = Decimal(str(float(value)))
    except (InvalidOperation, TypeError, ValueError) as exc:
        raise ValueError("invalid decimal") from exc
    if not result.is_finite():
        raise ValueError("expected finite value")
    return result


def check_currency(code):
    if not isinstance(code, str) or not code:
        raise ValueError(f"invalid currency code: {code!r}")
    return code


def quantize(amount):
    """Round to cents."""
    return as_decimal(amount).quantize(CENTS, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str

    def __post_init__(self):
        object.__setattr__(self, "amount", as_decimal(self.amount))
        check_currency(self.currency)

    def add(self, other):
        return Money(quantize(self.amount + other.amount), self.currency)

    def subtract(self, other):
        return Money(quantize(self.amount - other.amount), self.currency)

    def negate(self):
        return Money(-self.amount, self.currency)


@dataclass(frozen=True)
class Leg:
    account: str
    money: Money
"""Foreign-exchange rate table."""
from datetime import datetime

from models import Money, as_decimal, check_currency


class RateTable:
    """Point-in-time FX quotes: (base, quote, effective_at) -> rate."""

    def __init__(self):
        self._quotes = {}

    def set_rate(self, base, quote, effective_at, rate):
        check_currency(base)
        check_currency(quote)
        value = as_decimal(rate)
        self._quotes.setdefault((base, quote), []).append((effective_at, value))

    def rate(self, base, quote, at):
        """Latest rate for the pair; KeyError when none exist."""
        check_currency(base)
        check_currency(quote)
        if base == quote:
            return as_decimal(1)
        entries = self._quotes.get((base, quote), ())
        if not entries:
            raise KeyError(f"no rate {base}/{quote}")
        return max(entries, key=lambda entry: entry[0])[1]

    def convert(self, money, target, at):
        """Convert a Money into `target` currency."""
        check_currency(target)
        if money.currency == target:
            return money
        return Money(money.amount * self.rate(money.currency, target, at), target)
"""Multi-leg journal ledger."""
from collections import OrderedDict
from decimal import Decimal

from models import Leg, Money, quantize


class Ledger:
    """Append-only journal."""

    def __init__(self):
        self._entries = OrderedDict()

    def post(self, entry_id, legs):
        """Store a journal entry; returns its legs."""
        if not isinstance(entry_id, str) or not entry_id:
            raise ValueError("entry_id must be a nonempty string")
        legs = tuple(legs)
        if not legs:
            raise ValueError("journal entry requires legs")
        for leg in legs:
            if not isinstance(leg, Leg):
                raise ValueError("legs must be Leg instances")
        self._entries[entry_id] = legs
        return legs

    def entries(self):
        return list(self._entries.items())

    def balance(self, account, currency=None):
        totals = {}
        for legs in self._entries.values():
            for leg in legs:
                if leg.account == account:
                    key = leg.money.currency
                    totals[key] = totals.get(key, Decimal(0)) + leg.money.amount
        if currency is not None:
            return Money(totals.get(currency, Decimal(0)), currency)
        return {code: Money(amount, code) for code, amount in totals.items()}

    def accounts(self):
        seen = []
        for legs in self._entries.values():
            for leg in legs:
                if leg.account not in seen:
                    seen.append(leg.account)
        return seen
"""Ledger-vs-expected reconciliation."""
from dataclasses import dataclass
from decimal import Decimal

from models import Money, as_decimal, check_currency, quantize


@dataclass(frozen=True)
class Discrepancy:
    account: str
    currency: str
    expected: Decimal
    actual: Decimal
    difference: Decimal


class Reconciler:
    def __init__(self, ledger, rates):
        self.ledger = ledger
        self.rates = rates

    def trial_balance(self, account, target, at):
        balances = self.ledger.balance(account)
        total = Decimal(0)
        for money in balances.values():
            total += self.rates.convert(money, target, at).amount
        return Money(total, target)

    def reconcile(self, expected, at):
        discrepancies = []
        for account, currency in sorted(expected):
            want = as_decimal(expected[(account, currency)])
            have = self.ledger.balance(account, currency).amount
            if want != have:
                discrepancies.append(Discrepancy(account, currency, want, have,
                                                 want - have))
        return discrepancies
